import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

sigmoid_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor sigmoid_forward(torch::Tensor x);
"""

sigmoid_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

__global__ void sigmoid_kernel_cute(const float* __restrict__ X,
                                    float* __restrict__ Y,
                                    int64_t N)
{
  using Vec = float4;

  const int64_t nvec = N >> 2;

  Tensor mXv = make_tensor(make_gmem_ptr(reinterpret_cast<const Vec*>(X)), make_shape(nvec));
  Tensor mYv = make_tensor(make_gmem_ptr(reinterpret_cast<Vec*>(Y)),       make_shape(nvec));

  const int64_t tid    = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
  const int64_t stride = (int64_t)gridDim.x * blockDim.x;

  auto sig4 = [](Vec v) {
    Vec r;
    r.x = 1.0f / (1.0f + __expf(-v.x));
    r.y = 1.0f / (1.0f + __expf(-v.y));
    r.z = 1.0f / (1.0f + __expf(-v.z));
    r.w = 1.0f / (1.0f + __expf(-v.w));
    return r;
  };
  // Grid-stride loop unrolled by 4: each thread keeps up to four
  // independent 16-byte loads in flight (higher memory-level
  // parallelism) and the grid is 4x smaller, cutting block-scheduling
  // overhead and improving achieved occupancy for this DRAM-bound
  // streaming kernel. Accesses stay fully coalesced across warps.
  int64_t i = tid;
  const int64_t stride4 = stride << 2;
  for (; i + 3 * stride < nvec; i += stride4) {
    Vec v0 = mXv(i);
    Vec v1 = mXv(i + stride);
    Vec v2 = mXv(i + 2 * stride);
    Vec v3 = mXv(i + 3 * stride);
    mYv(i)              = sig4(v0);
    mYv(i + stride)     = sig4(v1);
    mYv(i + 2 * stride) = sig4(v2);
    mYv(i + 3 * stride) = sig4(v3);
  }
  for (; i < nvec; i += stride) {
    mYv(i) = sig4(mXv(i));
  }

  if (blockIdx.x == 0 && threadIdx.x == 0) {
    Tensor mX = make_tensor(make_gmem_ptr(X), make_shape(N));
    Tensor mY = make_tensor(make_gmem_ptr(Y), make_shape(N));
    for (int64_t i = (nvec << 2); i < N; ++i) {
      float v = mX(i);
      mY(i) = 1.0f / (1.0f + __expf(-v));
    }
  }
}

torch::Tensor sigmoid_forward(torch::Tensor x) {
  TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");

  auto x_c = x.contiguous();
  const int64_t N = x_c.numel();
  auto y = torch::empty_like(x_c);

  if (N == 0) {
    return y;
  }

  const float* x_ptr = x_c.data_ptr<float>();
  float* y_ptr = y.data_ptr<float>();

  constexpr int threads = 128;
  const int64_t nvec = N >> 2;
  int64_t wanted_blocks = (nvec + (int64_t)threads * 4 - 1) / ((int64_t)threads * 4);  // 4 float4 per thread
  if (wanted_blocks <= 0) wanted_blocks = 1;  // handles N < 4 tails
  const int blocks = wanted_blocks > 1048576 ? 1048576 : (int)wanted_blocks;

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  sigmoid_kernel_cute<<<blocks, threads, 0, stream>>>(x_ptr, y_ptr, N);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "CUTE sigmoid launch failed: ", cudaGetErrorString(err));

  return y;
}
"""

sigmoid_ext = load_inline(
    name="cute_sigmoid_inline",
    cpp_sources=sigmoid_cpp_decl,
    cuda_sources=sigmoid_cuda_src,
    functions=["sigmoid_forward"],
    extra_cflags=["-O3", "-std=c++17"],
    extra_cuda_cflags=["-O3", "-std=c++17"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Sigmoid activation implemented with a single custom CUTE/CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = sigmoid_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.sigmoid_forward(x)

